    margin: 5px;
    padding: 8px;
}

.tbDatasource-title {
    font-size: 1.200rem;
    font-weight: 500;
    padding-bottom: 10px;
}

.tbDatasource-table {
    width: 100%;
    box-shadow: 0 0 10px #ccc;
    border-collapse: collapse;
    white-space: nowrap;
    font-size: 1.000rem;
    color: #757575;
}

.tbDatasource-table td {
    position: relative;
    border-top: 1px solid rgba(0, 0, 0, 0.12);
    border-bottom: 1px solid rgba(0, 0, 0, 0.12);
    padding: 0px 18px;
    box-sizing: border-box;
}

descriptor.controllerScript:
self.onInit = function () {
  const s = self.ctx.$scope;

  // Initialize default values
  s.cpu_usage = '0.00';
  s.cpu_usage_ts = '';
  s.device_temperature = '0.00';
  s.device_temperature_ts = '';

  s.ram_used = 0;
  s.ram_total = 8192; // default total RAM (MB)
  s.ram_percent = 0;

  s.flash_used = 0;
  s.flash_total = 4096; // default total Flash (MB)
  s.flash_percent = 0;

  s.rsrp = -140;
  s.rsrp_ts = '';
  s.rsrp_percent = 0;

  s.rssi = -120;
  s.rssi_ts = '';
  s.rssi_percent = 0;

  s.uptime_raw = 0;
  s.uptime_formatted = '';

  s.usage_day = 0;
  s.usage_week = 0;
  s.usage_month = 0;

  s.modem = 'Unknown';
  s.network_type = 'Unknown';
  s.is_online = false;

  // Inject Tailwind if not already present
  if (!document.getElementById('tailwindcss')) {
    window.tailwind = {
      config: {
        safelist: [
          'grid', 'grid-cols-1', 'sm:grid-cols-2', 'md:grid-cols-3', 'lg:grid-cols-4',
          'gap-6', 'text-sm', 'font-semibold', 'rounded', 'bg-gray-200', 'transition-all',
          'duration-300', 'ease-out', 'text-gray-500', 'text-red-600', 'text-green-500',
          'p-4', 'mt-1', 'font-mono'
        ],
        corePlugins: { preflight: false }
      }
    };
    const script = document.createElement('script');
    script.src = 'https://cdn.tailwindcss.com';
    script.id = 'tailwindcss';
    script.onload = () => setTimeout(() => self.ctx.detectChanges(), 50);
    document.head.appendChild(script);
  } else {
    setTimeout(() => self.ctx.detectChanges(), 50);
  }
};

self.onDataUpdated = function () {
  const s = self.ctx.$scope;
  const data = self.ctx.data;

  // Helper to get the latest value for a key.
  const getValue = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    return entry && entry.data && entry.data.length ? entry.data.at(-1)[1] : null;
  };

  // Helper to get a timestamp.
  const getTS = (key) => {
    const entry = data.find(d => d.dataKey.name === key);
    return entry && entry.data && entry.data.length ? new Date(entry.data.at(-1)[0]).toLocaleTimeString() : new Date().toLocaleTimeString();
  };

  // --- CPU Usage ---
  let cpuRaw = getValue('cpu_usage');
  if (cpuRaw === null) {
    // Generate a random fraction between 0 and 1
    cpuRaw = (Math.random()).toFixed(2);
  }
  s.cpu_usage = (parseFloat(cpuRaw) * 100).toFixed(2);
  s.cpu_usage_ts = getTS('cpu_usage');

  // --- Temperature ---
  let tempRaw = getValue('device_temperature');
  if (tempRaw === null) {
    // Random temperature between 20°C and 100°C
    tempRaw = (20 + Math.random() * 80).toFixed(2);
  }
  s.device_temperature = parseFloat(tempRaw).toFixed(2);
  s.device_temperature_ts = getTS('device_temperature');

  // --- RAM ---
  let totalRAM = parseFloat(getValue('ram_total'));
  if (isNaN(totalRAM)) {
    totalRAM = 8192;
  }
  s.ram_total = totalRAM;

  let usedRAM = parseFloat(getValue('ram_used'));
  if (isNaN(usedRAM)) {
    // Random RAM usage between 0 and totalRAM
    usedRAM = parseFloat((Math.random() * totalRAM).toFixed(2));
  }
  s.ram_used = usedRAM;
  s.ram_percent = ((s.ram_used / s.ram_total) * 100).toFixed(2);

  // --- Flash ---
  let totalFlash = parseFloat(getValue('flash_total'));
  if (isNaN(totalFlash)) {
    totalFlash = 4096;
  }
  s.flash_total = totalFlash;

  let usedFlash = parseFloat(getValue('flash_used'));
  if (isNaN(usedFlash)) {
    // Random Flash usage between 0 and totalFlash
    usedFlash = parseFloat((Math.random() * totalFlash).toFixed(2));
  }
  s.flash_used = usedFlash;
  s.flash_percent = ((s.flash_used / s.flash_total) * 100).toFixed(2);

  // --- RSRP ---
  s.rsrp = parseFloat(getValue('rsrp'));
  if (isNaN(s.rsrp)) {
    // Random value between -140 and -40 dBm
    s.rsrp = Math.floor(-140 + Math.random() * 100);
  }
  s.rsrp_ts = getTS('rsrp');
  s.rsrp_percent = Math.max(0, Math.min(100, 100 - Math.abs((s.rsrp + 140) * 1.25)));

  // --- RSSI ---
  s.rssi = parseFloat(getValue('rssi'));
  if (isNaN(s.rssi)) {
    // Random value between -120 and -30 dBm
    s.rssi = Math.floor(-120 + Math.random() * 90);
  }
  s.rssi_ts = getTS('rssi');
  s.rssi_percent = Math.max(0, Math.min(100, 100 - Math.abs((s.rssi + 120) * 1.5)));

  // --- Uptime ---
  s.uptime_raw = parseFloat(getValue('uptime'));
  if (isNaN(s.uptime_raw)) {
    // Random uptime in seconds up to 24 hours (86400 seconds)
    s.uptime_raw = Math.floor(Math.random() * 86400);
  }
  if (s.uptime_raw > 0) {
    const h = Math.floor(s.uptime_raw / 3600);
    const m = Math.floor((s.uptime_raw % 3600) / 60);
    s.uptime_formatted = `${h}h ${m}m`;
  } else {
    s.uptime_formatted = '0h';
  }

  // --- Data Usage ---
  // For day, week, and month, assume telemetry is in KB; if missing, use random values.
  let dayUsage = parseFloat(getValue('data_usage_total_day'));
  if (isNaN(dayUsage)) {
    dayUsage = 1024 * Math.floor(Math.random() * 500); // up to ~500 MB in KB
  }
  s.usage_day = (dayUsage / 1024).toFixed(2);

  let weekUsage = parseFloat(getValue('data_usage_total_week'));
  if (isNaN(weekUsage)) {
    weekUsage = 1024 * Math.floor(Math.random() * 3000); // up to ~3000 MB in KB
  }
  s.usage_week = (weekUsage / 1024).toFixed(2);

  let monthUsage = parseFloat(getValue('data_usage_total_month'));
  if (isNaN(monthUsage)) {
    monthUsage = 1024 * Math.floor(Math.random() * 12000); // up to ~12000 MB in KB
  }
  s.usage_month = (monthUsage / 1024).toFixed(2);

  // --- Modem & Network ---
  s.modem = getValue('modem');
  if (!s.modem) {
    const modems = ['Modem A', 'Modem B', 'Modem C'];
    s.modem = modems[Math.floor(Math.random() * modems.length)];
  }

  s.network_type = getValue('network_type');
  if (!s.network_type) {
    const networks = ['4G', '5G', 'LTE'];
    s.network_type = networks[Math.floor(Math.random() * networks.length)];
  }

  let online = getValue('is_online');
  if (online === null) {
    online = Math.random() < 0.5;
  }
  s.is_online = online === true || online === 'true';

  // Update the UI
  self.ctx.detectChanges();
};

self.onDestroy = function () {
  console.log('🧹 Widget destroyed');
};

